CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, slug text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category_id uuid REFERENCES categories(id), slug text NOT NULL UNIQUE, name text NOT NULL, description text NOT NULL DEFAULT '', price_cents integer NOT NULL CHECK(price_cents>=0), supplier_cost_cents integer CHECK(supplier_cost_cents>=0), supplier_sku text, image_url text, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','archived')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), full_name text NOT NULL, email text NOT NULL, phone text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid REFERENCES customers(id), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','processing','shipped','delivered','cancelled','refunded')), subtotal_cents integer NOT NULL CHECK(subtotal_cents>=0), shipping_cents integer NOT NULL DEFAULT 0 CHECK(shipping_cents>=0), total_cents integer NOT NULL CHECK(total_cents>=0), payment_provider text, provider_payment_id text, idempotency_key text UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id uuid REFERENCES products(id), product_name text NOT NULL, unit_price_cents integer NOT NULL CHECK(unit_price_cents>=0), quantity integer NOT NULL CHECK(quantity>0));
CREATE TABLE IF NOT EXISTS supplier_fulfillments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id), supplier_name text NOT NULL, supplier_order_id text, tracking_code text, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log (id bigserial PRIMARY KEY, actor text NOT NULL DEFAULT 'system', action text NOT NULL, entity_type text NOT NULL, entity_id text, details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_products_status_created ON products(status,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_orders_status_created ON orders(status,created_at DESC);
